/**
 * Ticket triage by context (no keyword classifier).
 * Normalizes the helpdesk webhook payload and builds a Responses API request
 * with a strict JSON schema, so the model can only return valid values.
 */

// 1) Normalize payload (body can arrive as a JSON string, an object or at root)
const root = items[0]?.json ?? {};
let payload = root;

if (typeof root.body === "string") {
  const s = root.body.trim();
  if ((s.startsWith("{") && s.endsWith("}")) || (s.startsWith("[") && s.endsWith("]"))) {
    try { payload = JSON.parse(s); } catch (e) { payload = root; }
  }
}
if (root.body && typeof root.body === "object") {
  payload = root.body;
}

// 2) Extract ticket from the most common payload shapes
const id =
  payload.id ?? payload.ticket_id ?? payload.ticket?.id ??
  payload.data?.ticket?.id ?? root.id ?? root.ticket?.id;

const number =
  payload.number ?? payload.ticket?.number ??
  payload.data?.ticket?.number ?? root.number ?? root.ticket?.number ?? null;

const title =
  payload.title ?? payload.ticket?.title ??
  payload.data?.ticket?.title ?? root.title ?? "";

const body =
  payload.body ?? payload.article?.body ?? payload.ticket?.body ??
  payload.data?.ticket?.body ?? (typeof root.body === "string" ? root.body : "") ?? "";

const ticketId = typeof id === "string" ? id.trim() : id;
if (!ticketId) {
  throw new Error("Missing ticket 'id'. Payload: " + JSON.stringify(root).slice(0, 1500));
}

const ticket = {
  id: ticketId,                        // internal id (used by the API)
  number: String(number ?? ticketId),  // public ticket number (shown to humans)
  title: String(title || ""),
  body: String(body || ""),
};

// 3) Allowed values (must match the helpdesk dropdowns)
const groups = ["Field Support", "Service Desk", "Web Development", "Marketing", "Sales", "Projects"];
const types = ["Question", "Incident", "Request", "Recurring"];
const priorities = ["1 low", "2 normal", "3 high", "4 critical"];

// 4) Routing guide: team definitions + decision rules
const guide = `
You are an automatic triage system for IT helpdesk tickets. Return ONLY valid JSON matching the schema.

FIELDS:
- group: one of [${groups.join(", ")}]
- type: one of [${types.join(", ")}]
- priority: one of [${priorities.join(", ")}]
- confidence: 0..100
- reason: one short sentence that cites something in the ticket ("mentions X / requests Y / reports Z")
- suggested_solution: actionable technical steps, in the ticket's language, as "- " bullets
- customer_reply: a human reply in the ticket's language (3-7 lines), professional and empathetic, never promising deadlines

TEAM DEFINITIONS:
- Field Support: servers, physical networks, hardware, on-site visits, cabling, devices at the customer's premises.
  If the ticket is about scheduling a visit and mentions a physical place, classify as Field Support.
  NOT: web applications, online stores, orders or emails sent by a website (that is Web Development).
- Service Desk: remote/office IT: user accounts, Google Workspace / Microsoft 365 permissions, mailboxes, VPN, passwords, corporate PCs, Teams/SharePoint/OneDrive.
  NOT: transactional emails generated by a website.
- Web Development: websites and web apps (frontend/backend), CMS, plugins, bugs, hosting/DNS/SSL when the website is affected,
  e-commerce (orders, checkout, coupons) and transactional emails sent by the website.
  NOT: SEO indexing issues reported by Search Console or SEO tools (that is Marketing).
- Marketing: SEO/SEM/Ads, analytics (GA/GTM), campaigns, newsletters, content, social media, Search Console, indexing, sitemaps.
- Sales: quotes, pricing, contracts, renewals, proposals, billing for new projects.
- Projects: planning, scope, timing, milestones and project coordination.
  NOT: scheduling a one-off on-site visit.

HOW TO DECIDE:
- Use the full context (title + body). Never decide from a single word.
- Mixed topics: choose the team responsible for the main or most urgent part.
- Ambiguous: choose "Field Support" with low confidence (50-65) and ask for specific data.

TYPE: Incident = something broken / error / outage. Request = change / improvement / new setup.
Question = informational. Recurring = happens repeatedly ("always", "every week").

PRIORITY: 4 critical = production down / business stopped / security / data loss.
3 high = large impact or key process. 2 normal = standard issue. 1 low = cosmetic / minor question.

CONFIDENCE: 90-100 clear signals. 70-89 mostly clear, 1-2 details missing. 50-69 ambiguous.

QUALITY RULES:
- Never invent causes or definitive fixes.
- If data is missing, ask exactly for it: URL, affected user, time, screenshot, steps to reproduce, environment.
- suggested_solution: always "- " bullets with verifiable actions.
- customer_reply: thank, confirm review, ask for 2-3 missing details, no deadlines.
`;

// 5) Strict output schema (Structured Outputs)
const schema = {
  type: "object",
  additionalProperties: false,
  properties: {
    group: { type: "string", enum: groups },
    type: { type: "string", enum: types },
    priority: { type: "string", enum: priorities },
    confidence: { type: "integer", minimum: 0, maximum: 100 },
    reason: { type: "string" },
    suggested_solution: { type: "string" },
    customer_reply: { type: "string" },
  },
  required: ["group", "type", "priority", "confidence", "reason", "suggested_solution", "customer_reply"],
};

// 6) Responses API payload
const openai_payload = {
  model: "gpt-4o-mini",
  instructions:
    "Return ONLY valid JSON matching the schema. " +
    "Decide group/type/priority/confidence from the context and the definitions. " +
    "Do not invent causes; if data is missing, ask for it in suggested_solution and customer_reply.",
  input: [
    {
      role: "user",
      content:
        `${guide}\n\nTicket:\nID: ${ticket.number}\nTitle: ${ticket.title}\nMessage: ${ticket.body}\n\n` +
        `Return the final JSON following the schema.`,
    },
  ],
  text: {
    format: { type: "json_schema", name: "ticket_triage_v1", strict: true, schema },
  },
};

return [{ json: { ticket, openai_payload } }];

// Parse the model output and apply safe fallbacks.
const prep = $node["Prepare ticket + LLM request"].json;
const ticket = prep.ticket;
if (!ticket?.id) throw new Error("ticket.id not found in the prepare node.");

const openai = items[0].json || {};

// Responses API: output[0].content[0].text holds the JSON string
const outputText =
  openai.output?.[0]?.content?.[0]?.text ??
  openai.output?.[0]?.content?.[0]?.output_text ??
  openai.output_text ?? '';

let parsed;
try {
  parsed = JSON.parse(String(outputText || '').trim());
} catch (e) {
  parsed = {
    group: 'Field Support',
    type: 'Question',
    priority: '2 normal',
    confidence: 0,
    reason: 'Could not parse JSON: ' + String(outputText || '').slice(0, 300),
    suggested_solution: '- Review the ticket manually and ask for URL/time/screenshot.\n- Retry the classification.',
    customer_reply: 'Thanks for letting us know. We are looking into it. Could you send us the affected URL, the approximate time of the error and a screenshot so we can reproduce it?'
  };
}

let group = parsed.group || 'Field Support';
let type = parsed.type || 'Question';
let priority = parsed.priority || '2 normal';
const confidence = Number.isFinite(parsed.confidence) ? parsed.confidence : 0;
const reason = parsed.reason || '';
let solution = parsed.suggested_solution || '';
let reply = parsed.customer_reply || '';

// Low confidence -> route to the default queue with normal priority
if (confidence < 60) {
  group = 'Field Support';
  priority = '2 normal';
}

if (!solution) solution = '- Check logs and reproduce the issue.\n- Ask for URL/time/steps if missing.';
if (!reply) reply = 'Thanks for letting us know. We are reviewing the case. Could you share the affected URL and a screenshot of the error?';

// Internal note for the agent (the AI suggests, a human decides)
const noteBody =
  `AI triage suggestion:\n` +
  `Group: ${group}\nType: ${type}\nPriority: ${priority}\nConfidence: ${confidence}\nReason: ${reason}\n\n` +
  `Suggested solution:\n${solution}\n\n` +
  `Suggested customer reply:\n${reply}\n`;

return [{
  json: {
    ticket_id: ticket.id,
    ticket_number: ticket.number,
    ticket_title: ticket.title,
    group, type, priority, confidence, reason,
    suggested_solution: solution,
    customer_reply: reply,
    noteBody
  }
}];

