// Build one row for the triage log table (Excel / any spreadsheet).
const prep = $node["Prepare ticket + LLM request"].json;
const triage = items[0].json;
const ticket = prep.ticket || {};
const now = new Date().toISOString();

const ticket_id = String(triage.ticket_number ?? triage.ticket_id ?? ticket.id ?? "");
const bodyPreview = String(ticket.body ?? "")
  .replace(/<[^>]*>?/gm, '').replace(/\s+/g, ' ').trim().slice(0, 500);

// Prefix with a space so spreadsheets never evaluate the text as a formula
const safe = v => { const s = String(v ?? ''); return /^[=+\-@]/.test(s) ? ' ' + s : s; };

const rowValues = [
  `${ticket_id}-${$execution.id}`,  // stable log id per execution
  now,
  ticket_id,
  safe(ticket.title),
  safe(bodyPreview),
  triage.group ?? "",
  triage.type ?? "",
  triage.priority ?? "",
  triage.confidence ?? "",
  safe(triage.suggested_solution),
  safe(triage.customer_reply)
];

return [{ json: { rowValues } }];
